L10_1.m_Crash = 15
L10_1.m_Talk_KOREA = "아이고, 아파라! 하마터면 머리에 빵구 날 뻔했네!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "あ～いった～！　危うく頭に穴が開くとこやったわ！"
L10_1.m_Talk_ENG = "Oof! I was this close to gettin’ a hole in my head!"
L10_1.m_Talk_TWN = "哎唷！好痛喔！頭都要破了啦！"
L10_1.m_Talk_THA = "อุ่ย! หัวเกือบเป็นรูแล้วนิ!"
L10_1.m_Talk_VTN = "Oof! Suýt thì đầu tôi thủng một lỗ rồi!"
L10_1.m_Talk_SCN = "哎呦，疼死了！咱的腰差点就断了！"
L10_1.m_Talk_DEU = "Aua, das tut aber weh! Mein Kopf wäre beinahe durchbohrt worden!"
L10_1.m_Talk_FRA = "Aïe, ça fait mal ! Pfiouh, un peu plus et je terminais avec un trou dans la tête..."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5000209
