L11_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L11_1.m_Pos = "L"
L11_1.m_Crash = 20
L11_1.m_Talk_KOREA = "왜 정신 사납게 동아리실에서 이러는 거예요!"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "なんでよりによって部室でやるんですか！"
L11_1.m_Talk_ENG = "Stop distracting everyone in the club room!"
L11_1.m_Talk_TWN = "你在幹嘛啦？把社辦搞得亂七八糟的！"
L11_1.m_Talk_THA = "หยุดทำทุกคนเสียสมาธิซักทีเถอะครับ!"
L11_1.m_Talk_VTN = "Đừng có khiến mọi người trong phòng CLB phân tâm nữa!"
L11_1.m_Talk_SCN = "所以说啊，你为什么要在社团活动室里这样闹腾呢！"
L11_1.m_Talk_DEU = "Hör auf, alle im Clubraum abzulenken!"
L11_1.m_Talk_FRA = "T'es vraiment obligée de tout casser comme ça ?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5000209
L12_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L12_1.m_Pos = "L"
L12_1.m_Talk_KOREA = "그 필살기인가 뭔가 하는 거 그냥 제가 적당히 찾아서 그려준다니까요?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "その必殺技とやら、僕が適当に探して描いてあげますってば！"
L12_1.m_Talk_ENG = "I told you, I’ll just grab and copy a couple of moves for your special move or whatever!"
L12_1.m_Talk_TWN = "那個必殺技還什麼的，我就說會找個差不多的來畫嘛！"
L12_1.m_Talk_THA = "บอกแล้วไงครับ ผมแค่จะดูแล้วลอกท่าสองท่าไปทำท่าไม้ตายอะไรของคุณนั่นน่ะ!"
L12_1.m_Talk_VTN = "Em đã nói với chị rồi, em sẽ chỉ nắm bắt và sao chép vài động tác cho chuyển động đặc biệt thôi!"
L12_1.m_Talk_SCN = "那个必杀技什么的，我都说了我会画出差不多的？"
L12_1.m_Talk_DEU = "Ich habe dir gesagt, ich schnappe mir einfach ein paar Vorlagen und kopiere sie für deine ultimative Fähigkeit!"
L12_1.m_Talk_FRA = "C'est pourtant pas compliqué ! Choisis un des coups dans la liste et je te le dessine, bon sang !"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@13#Talk"
