L14_1 = {}
L15_1 = 2
L16_1 = 0.15
L14_1[1] = L15_1
L14_1[2] = L16_1
L13_1.m_Bounce = L14_1
L13_1.m_Talk_KOREA = "마! 됐다! 이제부턴 내 자존심에 문제다! 감 잡았으니까 이제 쪼매만 더 하면……"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "もうええわ！　ここからはウチのプライドがかかってるんやで！　大体掴めてきたから、もう少しで……"
L13_1.m_Talk_ENG = "And I’m tellin’ ya, that won’t do! It's a matter of pride! I’ve got the hang of it, just a lil more–"
L13_1.m_Talk_TWN = "喂！你閉嘴！現在是面子問題！我抓到感覺了，只要再一下……"
L13_1.m_Talk_THA = "และฉันก็บอกอยู่นี่ไงว่าแบบนั้นไม่ได้หรอก! มันเรื่องความภาคภูมิใจนะ! ฉันทำได้หรอกน่า แค่อีกนิด–"
L13_1.m_Talk_VTN = "Và chị sẽ nói với nhóc, như thế là không ổn rồi mà! Đó là vấn đề về sự tự hào! Chị đã hiểu rõ về nó, chỉ một chút nữa thôi–"
L13_1.m_Talk_SCN = "喂！别说了！从现在开始，这是关乎咱自尊心的问题！现在已经找到感觉了，只要再努力一点——"
L13_1.m_Talk_DEU = "Und ich sage dir, das geht nicht! Es geht hier schließlich um meine Ehre! Ich habe den Dreh gleich raus, nur noch ein bisschen –"
L13_1.m_Talk_FRA = "Je veux pas, je te dis ! C'est une question de fierté, tu piges ? J'y suis presque, encore un peu..."
L14_1 = {}
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 5000209
L14_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L14_1.m_bWaitClick = false
L14_1.m_fWaitTime = 0.5
L14_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE"
