L15_1 = {}
L15_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 5000209
L15_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Talk_KOREA = "……속보입니다. 어젯밤, 서울시 A구의 한 공장에서 폭발 사고가 있었습니다."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "……続報です。昨夜、ソウル市A区のある工場で、爆発事故が起こりました。"
L15_1.m_Talk_ENG = "...Breaking news: An explosion occurred at a factory in District A last night."
L15_1.m_Talk_TWN = "……新聞快報，昨天晚上在首爾市A區某間工廠發生爆炸意外。"
L15_1.m_Talk_THA = "...ข่าวด่วน เกิดเหตุระเบิดในย่าน A เมื่อคืนนี้"
L15_1.m_Talk_VTN = "...Tin nóng: Đêm qua đã xảy ra vụ nổ tại nhà máy ở Khu A."
L15_1.m_Talk_SCN = "……现在插播一条速报！昨天夜里，市A区某工厂内发生了爆炸事故。"
L15_1.m_Talk_DEU = "... Eilmeldung: Gestern Abend kam es in einer Fabrik im Bezirk A zu einer Explosion."
L15_1.m_Talk_FRA = "... Flash info. Hier soir, une explosion a eu lieu dans une usine du secteur A."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 5000209
L16_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Talk_KOREA = "원인은 가스 누출로 인한 폭발 사고로 추정되며…… 생존자들의 증언에 따르면 짐승 울음과 비슷한 소리를…… 경찰은 가스 중독에 의한 환각 및 환청 증세로……"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "原因はガス漏れによる爆発事故と推定され……生存者の証言によりますと、獣の鳴き声のような音を……警察はガス中毒により幻覚および幻聴の病症と……"
L16_1.m_Talk_ENG = "Forensics assumes that a gas leak was what caused the incident–... While survivors testify that they heard a strange animal-like cry–... Police forces confirmed the testimonies as audio-visual hallucinations due to gas poisoning–..."
L16_1.m_Talk_TWN = "意外發生原因推測是由於瓦斯外洩導致……倖存者表示有聽到類似野獸的嚎叫聲和哀號聲……警察表示可能是瓦斯中毒引起的幻聽或幻覺……"
L16_1.m_Talk_THA = "หน่วยพิสูจน์หลักฐานสันนิษฐานว่าสาเหตุเกิดจากแก๊สรั่ว–... ในขณะที่ผู้รอดชีวิตให้ปากคำว่าได้ยินเสียงร้องแปลกๆ เหมือนสัตว์–... ด้านเจ้าหน้าที่ตำรวจยืนยันถึงคำให้การว่ามีอาการเห็นภาพหลอนทั้งภาพและเสียงเนื่องจากแก๊สพิษ–..."
L16_1.m_Talk_VTN = "Tổ pháp ý đoán định rằng khí gas rò rì là nguyên nhân gây ra vụ việc-...Trong khi những người sống sót khẳng định họ đã nghe thấy tiếng kêu như tiếng động vật rất kỳ lạ-...Lực lượng cảnh sát đã xác nhận lời khai trên là do ảo giác nghe-nhìn vì độc khí gas-..."
L16_1.m_Talk_SCN = "据推断，爆炸事故的原因是煤气泄漏……幸存者表示，听到了类似野兽嚎叫的声音……警察称这是煤气中毒引起的幻觉和幻听症状……"
L16_1.m_Talk_DEU = "Die Forensik geht davon aus, dass ein Gasleck die Ursache für den Vorfall war ... Während Überlebende bezeugen, dass sie einen seltsamen, tierähnlichen Schrei gehört haben ... Geht Polizei davon aus, dass diese akustischen Halluzinationen auf eine Gasvergiftung zurückzuführen sind ..."
L16_1.m_Talk_FRA = "D'après ce que l'on sait, l'incident aurait été provoqué par une fuite de gaz... les témoins qui étaient présents sur place ont évoqué les cris d'une bête enragée... la police semble écarter cette piste et impute la fantaisie de ces témoignages à une hallucination au gaz..."
