L18_1.m_Crash = 15
L18_1.m_Talk_KOREA = "잠깐…… 저기 저희 동네인 것 같은데요!?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "ちょっ……あれ、僕の住んでる町じゃ！？"
L18_1.m_Talk_ENG = "Wait... That looks like the factory in our town!"
L18_1.m_Talk_TWN = "等等……那好像是我住的地方！？"
L18_1.m_Talk_THA = "เดี๋ยวนะ... นั่นเหมือนโรงงานในเมืองเราเลยนี่ครับ"
L18_1.m_Talk_VTN = "Chờ chút...Trong như nhà máy ở thị trấn chúng ta ấy!"
L18_1.m_Talk_SCN = "等等……那里好像是我们社区呢！？"
L18_1.m_Talk_DEU = "Moment mal ... Das sieht aus wie die Fabrik in meiner Nachbarschaft!"
L18_1.m_Talk_FRA = "Attendez... c'est pas notre quartier, ça ?"
