L19_1.m_Talk_KOREA = "뭐라고? 진짜가?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "何やて？　ホンマか？"
L19_1.m_Talk_ENG = "What? Really?"
L19_1.m_Talk_TWN = "你說啥？真的嗎？"
L19_1.m_Talk_THA = "หา? จริงเหรอ?"
L19_1.m_Talk_VTN = "Cái gì? Thật sao?"
L19_1.m_Talk_SCN = "你说什么？真的吗？"
L19_1.m_Talk_DEU = "Was hast du gesagt? Echt?"
L19_1.m_Talk_FRA = "De quoi ? Sérieux ?"
L20_1 = {}
L20_1.m_CutScenKey_Talk = "GAMECIRCLE_ACT2_STAGE3_START@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 5000209
L20_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L20_1.m_bWaitClick = true
