L20_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L20_1.m_Pos = "L"
L20_1.m_Crash = 10
L20_1.m_Talk_KOREA = "그런 것 같아요. 와, 그 커다란 공장이 폭삭 주저앉았잖아!?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "そうみたいです。うわ、あの大きい工場が完全に崩れてる！？"
L20_1.m_Talk_ENG = "I think so. Whoa, I can’t believe such a big factory could get destroyed that easily!"
L20_1.m_Talk_TWN = "好像是，哇，那麼大間的工廠瞬間倒塌欸！？"
L20_1.m_Talk_THA = "ผมว่าใช่นะครับ เหวอ ไม่อยากเชื่อเลยว่าโรงงานใหญ่ขนาดนั้นจะถูกทำลายได้ง่ายๆ"
L20_1.m_Talk_VTN = "Em nghĩ vậy. Whoa, không thể tin nổi một nhà máy lớn như thế lại bị phá hủy dễ dàng như vậy!"
L20_1.m_Talk_SCN = "好像是。哇，那么大的工厂一下子倒塌了！？"
L20_1.m_Talk_DEU = "Ich denke schon. Wow, ich kann nicht glauben, dass eine so große Fabrik so leicht zerstört werden kann!"
L20_1.m_Talk_FRA = "On dirait bien. Ouah, comment une usine aussi grosse peut voler en fumée comme ça ?"
