L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "요즘 들어 저런 사고 꽤 많이 일어나는 것 같아."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "最近、ああいう事故が結構多いみたいだね。"
L23_1.m_Talk_ENG = "It looks like there’s a lot of incidents around town."
L23_1.m_Talk_TWN = "最近好像很多這種意外。"
L23_1.m_Talk_THA = "เหมือนจะมีเรื่องเกิดขึ้นไปทั่วเมืองเลยนะ"
L23_1.m_Talk_VTN = "Có vẻ như khắp thị trấn đang xảy ra rất nhiều vụ việc."
L23_1.m_Talk_SCN = "最近好像经常发生那种事故。"
L23_1.m_Talk_DEU = "Es scheint, dass solche Vorfälle heutzutage ziemlich häufig vorkommen."
L23_1.m_Talk_FRA = "Il y a pas mal de grabuge dans le quartier, ces temps-ci."
L24_1 = {}
