L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "다섯 번……. 이번 달에만…… 크고 작은 거 합하면."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "5回……今月だけで……大小合わせて。"
L24_1.m_Talk_ENG = "The fifth time... it is... this month."
L24_1.m_Talk_TWN = "五次……光是這個月……大大小小加起來。"
L24_1.m_Talk_THA = "นี่ครั้งที่ห้า... แล้ว... เดือนนี้"
L24_1.m_Talk_VTN = "Trong tháng này...là...lần thứ năm rồi."
L24_1.m_Talk_SCN = "五起……光是这个月……大大小小的事故加起来。"
L24_1.m_Talk_DEU = "Das fünfte Mal ... allein in diesem Monat .. wenn man die kleinen und großen Vorfälle zusammenrechnet."
L24_1.m_Talk_FRA = "C'est déjà le cinquième incident... ce mois-ci."
