L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 5000209
L28_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_LAUGH"
L28_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L28_1.m_Pos = "C"
L28_1.m_Crash = 10
L28_1.m_Talk_KOREA = "아, 아하하! 마, 박스! 니 뭐 묵고 싶은 거 없나? 누나랑 잠깐 나가서 아이스크림 사올까?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "あ、あはは！　なあ、ダンボール！　なんか食べたいものない？　お姉さんと一緒に、ちょっとアイスでも買いにいかへん？"
L28_1.m_Talk_ENG = "A-ah ha ha! Hey, Box! Are ya feelin' hungry? Wanna go get ice cream with me?"
L28_1.m_Talk_TWN = "哈，哈哈！喂，紙箱！你有想吃什麼東西嗎？我們一起去買冰淇淋回來吧？"
L29_1 = "อะ-อะฮ่าฮ่า! นี่ บ็อกซ์! หิวยังนิ? ไปหาไอติมกินกันมะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "A-ah ha ha! Này, Box! Nhóc có cảm thấy đói không? Có muốn đi ăn kem với chị không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "啊，啊哈哈！喂，箱子君！你想不想吃点东西？跟姐姐一起去买冰淇淋啊？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ahaha! Hey, Box! Bist du hungrig? Willst du mit mir ein Eis essen gehen?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ah, ha ha ha ! Hé, carton ! T'as pas faim ? Et si on allait casser la croûte ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "GAMECIRCLE_ACT2_STAGE3_START@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5000209
L29_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_SERIOUS2"
L29_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L29_1.m_Pos = "C"
L30_1 = "네? 갑자기 왜요? 여기 산기슭이라 슈퍼까지 한참 걸리잖아요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "え？　いきなりどうしたんですか？　ここは山のふもとだからスーパーまで結構かかるじゃないですか。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Huh? Why, all of a sudden? It takes ages to get to the store from here."
L29_1.m_Talk_ENG = L30_1
L30_1 = "蛤？這麼突然？這裡在山腳下，離便利商店很遠欸？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หือ? ไหงจู่ก็มางี้ละครับ? จากนี่ไปร้านนี่เป็นชาติเลยนะครับ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Huh? Tự nhiên sao lại thế? Từ đây tới cửa hàng tốn thời gian lắm."
L29_1.m_Talk_VTN = L30_1
L30_1 = "啊？为什么突然要买冰淇淋？这里是山脚下，去超市得走很远呢。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Häh? Warum denn so plötzlich? Von hier aus dauert es doch ewig bis zum Supermarkt."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Hein ? Comme ça, sans prévenir ? Mais la supérette est à des kilomètres..."
L29_1.m_Talk_FRA = L30_1
