L33_1 = "R_M_I"
L32_1.m_Pos = L33_1
L32_1.m_Crash = 15
L33_1 = "와는 뭔 놈의 와고? 누나가 사준다고 하믄, 그냥 네 하고 후딱 나오는거지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "何言うてんねん！　お姉さんがおごってあげるって言うてんやから、素直にはい言うてはよ出てこい。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Ah? Don’t be an insolent brat and obey when big sis tells ya to."
L32_1.m_Talk_ENG = L33_1
L33_1 = "蛤什麼蛤？姊姊說要買給你，你應該要立刻答應，然後小跑步出列唄！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอ๊า? เวลาพี่สาวบอกให้อะไรก็ทำไปสิ อย่าดื้อเด้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ah? Đừng có ra vẻ một thằng nhóc xấc láo và hãy nghe lời khi chị gái bảo nhóc làm bất cứ cái gì."
L32_1.m_Talk_VTN = L33_1
L33_1 = "没有为什么。姐姐说要给你买好吃的，你就该乖乖说“好”才是。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Sei kein unverschämter Bengel und gehorche, wenn deine große Schwester dir was sagt."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Et alors ? Sois un gentil garçon et fais ce que je te dis, ok ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
