L35_1 = 2
L36_1 = 0.15
L34_1[1] = L35_1
L34_1[2] = L36_1
L33_1.m_Bounce = L34_1
L34_1 = "자자, 얼른 따라온나! 누나가 떡볶이도 사줄게!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ささ、はよ来てや！　トッポッキもおごってやるから！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Come along now! I’ll even buy you rice cake on our way back!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "快點，趕快跟上！! 姊姊再加碼辣炒年糕！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "มาน่า! เดี๋ยวตอนกลับซื้อเค้กข้าวให้กินนิ!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đi nào! Trên đường về chị sẽ mua cho một cái bánh gạo nhé!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "好了，快点跟上！姐姐给你买炒年糕！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Na los, komm mit! Ich werde dir auch Reiskuchen kaufen!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Allez, on se bouge ! Si t'es gentil, je t'achèterai même des gâteaux de riz sur le chemin du retour !"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "GAMECIRCLE_ACT2_STAGE3_START@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 5000209
