L34_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L34_1.m_Pos = "L"
L34_1.m_Crash = 15
L35_1 = "아니…… 바빠 죽겠는데, 갑자기 무슨……!?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "え……忙しいのに、何を急に……！？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Geez... We’ve got so much to do. What’s your deal?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "討厭……我很忙欸，幹嘛突然……！？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ให้ตายสิ... เรามีอะไรต้องทำตั้งเยอะนะครับ จะเอาอะไรเนี่ย?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Geez... Chúng ta có quá nhiều việc phải làm. Chị muốn gì?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "不是……都要忙死了，你到底在想什么啊……！？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Aber ... wir haben doch so viel zu tun. Was soll das denn plötzlich ...?!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Pff... Avec tout le boulot qu'on a, c'est vraiment pas le moment !"
L34_1.m_Talk_FRA = L35_1
