L42_1.m_Pos = "C"
L43_1 = "……결국, 오늘은 별로 하지도 못 했잖아?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……結局、今日は全然進まなかったな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...We ended up falling behind schedule!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "……結果，今天根本零進度欸？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...เราจะเสร็จไม่ทันเอานะครับแบบนี้!"
L42_1.m_Talk_THA = L43_1
L43_1 = "...Chúng ta thể nào cũng chậm tiến độ!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "……到最后，今天也没做什么啊？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Am Ende haben wir heute fast nichts geschafft."
L42_1.m_Talk_DEU = L43_1
L43_1 = "... On a rien fait aujourd'hui, on prend du retard sur le planning !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "GAMECIRCLE_ACT2_STAGE3_START@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 5000209
