L43_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L43_1.m_Pos = "C"
L43_1.m_Crash = 10
L44_1 = "다음 코미페까지 이제 몇 주 남지도 않았는데…… 다들 이래도 괜찮은 거 맞아……?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "次のコミフェまであと何週も残ってないのに……みんなこれで大丈夫なのかな……？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "It’s only a couple of weeks until the next Comic Festival... Is it acceptable for everyone to be like this?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "距離下次動漫展只剩幾個星期的時間……這樣沒問題嗎……？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "อีกสองอาทิตย์ก็ถึงเทศกาลการ์ตูนครั้งต่อไปแล้ว... ทุกคนมาทำแบบนี้นี่ได้เหรอครับ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Chỉ còn vài tuần nữa là Lễ Hội Truyện Tranh tiếp theo diễn ra...Mọi người cứ thế này thì có chấp nhận được không cơ chứ?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "距离下届漫画节就剩几周时间了……大家这样真的没关系吗……?"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Es sind nur noch ein paar Wochen bis zum nächsten Comic-Festival ... Können wir es wirklich bis dahin fertigkriegen ...?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Et la Comic Expo qui approche à grands pas... on peut vraiment se permettre de glander comme ça ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
