L50_1 = "……미리네 누나잖아? 누나가 왜 우리 동네에 있는 거지?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "……マリさん？　どうしてこの町にいるんだろう？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "...That’s Rinae. Why's she over at my town?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "……宓璃奈姊姊？她為什麼在我家附近？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "...นั่นมิรีนนี่ เธอมาทำอะไรอยู่ที่เมืองผมน่ะ?"
L49_1.m_Talk_THA = L50_1
L50_1 = "...Đó là Rinae. Tại sao chị ấy lại ở thị trấn này?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "……这不是茉莉奈姐姐嘛？姐姐怎么在我们社区附近？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "... Das ist doch Rinae. Warum ist sie denn in meiner Nachbarschaft?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Mais... c'est Rinae ? Qu'est-ce qu'elle fait dans le quartier ?"
