L5_1 = "헉…… 허억! 엄청 빠르잖아? 계속 뛰었는데도 전혀 못 쫓아가겠어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "はあ……はあ！　すごい速さだ！　ずっと走ってるのに全然追いつけない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "*Huff...* *Huff...!* She’s so fast! I can’t even keep up with her."
L4_1.m_Talk_ENG = L5_1
L5_1 = "哇……哇咧！會不會跑太快？快到我根本追不上。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "*แฮ่ก...* *แฮ่ก...!* เธอเร็วเป็นบ้าเลยแฮะ! ตามไม่ทันเลยเนี่ย"
L4_1.m_Talk_THA = L5_1
L5_1 = "*Hộc...* *Hộc...!* Chị ấy nhanh quá! Mình không thể nào theo kịp nổi."
L4_1.m_Talk_VTN = L5_1
L5_1 = "哈……哈啊！好快啊！我一直跑也完全追不上呢。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "*Keuch* *schnauf* Sie ist verdammt schnell! Obwohl ich gerannt bin, konnte ich nicht mit ihr mithalten."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Haa... Haa ! Elle est trop rapide, j'arrive pas à la suivre !"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "GAMECIRCLE_ACT2_STAGE3_START@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5000209
L5_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L5_1.m_Pos = "C"
L6_1 = "대체 어딜 저렇게 급하게 가는 거야? 저쪽은……"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あんなに急いでいったいどこに行くんだろう？　あっちは……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Where is she headed to? Isn't that the direction of..."
L5_1.m_Talk_ENG = L6_1
L6_1 = "她跑這麼急是要去哪裡？那邊是……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "จะไปไหนของเธอนะ? ทางนั้นมันไป..."
L5_1.m_Talk_THA = L6_1
L6_1 = "Chị ấy định đi đâu vậy? Đó không phải là hướng của..."
L5_1.m_Talk_VTN = L6_1
L6_1 = "她这是急着去哪儿啊？那头是……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Wohin in aller Welt geht sie bloß so eilig? Die Richtung ..."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Où est-ce qu'elle va comme ça ? Hein, mais... ?"
