L7_1 = "앗? 그러고보니 저긴 가스 누출 사고가 있던 공장 쪽이잖아?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あっ？　そういえば、あっちはガス漏れ事故があった工場の方？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Huh? That’s where the gas exploded at the factory!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "嗯？那裡不是發生瓦斯外洩意外的工廠嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "หือ? นั่นมันที่ที่โรงงานแก๊สระเบิดนี่!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Huh? Đó là nơi xảy ra vụ nổ khí gas ở nhà máy!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "啊？我想起来了，那不是发生煤气泄漏事故的工厂那边吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Hä? Ist das nicht die Fabrik, in der es dieses Gasleck gab?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Maintenant que j'y pense, c'est par là que l'explosion de la dernière fois a eu lieu..."
L6_1.m_Talk_FRA = L7_1
