L10_1.m_Pos = "R"
L11_1 = "늦을 거야……. 하고 있거든…… <color=#ffd34c>현장 실습</color>."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "遅くなる……やってるから……<color=#ffd34c>現場実習</color>。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "They’re coming in late... <color=#ffd34c>Field training</color>… they're doing."
L10_1.m_Talk_ENG = L11_1
L11_1 = "遲到……她們……<color=#ffd34c>現場實習</color>。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "พวกนั้นจะมาสาย... พวกนั้นไป... <color=#ffd34c>ฝึกภาคสนาม</color>..อยู่"
L10_1.m_Talk_THA = L11_1
L11_1 = "Họ đến muộn... Họ đã đi... <color=#ffd34c>huấn luyện thực địa </color> rồi"
L10_1.m_Talk_VTN = L11_1
L11_1 = "会晚一点……<color=#ffd34c>现场实习</color>……她们在做。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Sie kommen später ... Sie absolvieren gerade ... ein <color=#ffd34c>Feldtraining</color>."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Elles seront en retard... parce qu'elles suivent un <color=#ffd34c>entraînement spécial</color>."
L10_1.m_Talk_FRA = L11_1
