L12_1.m_Pos = "C"
L12_1.m_Crash = 15
L13_1 = "그러고보니…… 그때 보라 누나, 분명 현장 실습이라고 했어."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そういえば……あの時のシホさん、確かに現場実習って言ってた。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Come to think of it... Bora said the word \"field training\"."
L12_1.m_Talk_ENG = L13_1
L13_1 = "這麼說來……那時候寶拉姊姊好像有提到什麼現場實習的。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "จะว่าไป... เธอบอกว่า \"ฝึกภาคสนาม\" นี่"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nghĩ lại thì… Bora đã nói từ ”huấn luyện thực địa”."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我想起来了……那时宝拉姐姐说的分明是她们在现场实习。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wenn ich so darüber nachdenke ... hat Bora von „Feldtraining“ gesprochen."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Attends un peu... cet entraînement spécial dont parlait Bora..."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "GAMECIRCLE_ACT2_STAGE3_START@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
