L13_1.m_Pos = "C"
L14_1 = "하지만 무슨 현장 실습이길래, 사고 현장에서 한다는 거야?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "でも、事故現場なんかでやる現場実習って、いったい何だろう？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But what kind of field training takes place at an accident scene?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "不過是什麼現場實習？還需要到意外現場？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่ฝึกภาคสนามแบบไหนไปทำกันในที่เกิดอุบัติเหตุล่ะ?"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng loại huấn luyện thực địa nào lại diễn ra ở hiện trường tai nạn chứ?"
L13_1.m_Talk_VTN = L14_1
L14_1 = "可是究竟是什么现场实习，是在事故现场做的呢？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber welche Art von Feldtraining findet an einem Unfallort statt?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Soit, mais pourquoi sur le site d'une explosion ? Ça n'a aucun sens."
L13_1.m_Talk_FRA = L14_1
