L30_1 = "아니야, 뭔가 달라! 네 발로 움직이지만…… 저걸 생물체라고 하기엔……."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "いや、何かが違う！　四つ足で歩いてるけど……あれは生き物というより……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "No, they’re somewhat different... They move on fours... but I wouldn’t call them organisms..."
L29_1.m_Talk_ENG = L30_1
L30_1 = "不對，不太一樣！雖然都是用四隻腳在移動……但與其說是生物……"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ไม่สิ มันดูไม่เหมือนนะ... พวกมันเดินสี่ขา... แต่คงเรียกว่าสิ่งมีชีวิตไม่ได้หรอก..."
L29_1.m_Talk_THA = L30_1
L30_1 = "Không, chúng hơi khác một chút... Chúng di chuyển bằng bốn chân... nhưng mình không thể gọi chúng là sinh vật được..."
L29_1.m_Talk_VTN = L30_1
L30_1 = "不对，感觉不一样！虽然使用四条腿走路……但那个说是生物体有点……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Nein, sie sind irgendwie anders ... Obwohl sie sich auf allen Vieren bewegen ... würde ich sie nicht als Lebewesen bezeichnen ..."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Non, ils ont quelque chose de différent ! Ils ont quatre pattes, et pourtant... on ne dirait pas des bêtes !"
L29_1.m_Talk_FRA = L30_1
