L31_1 = "으윽……! 속이 너무 안 좋아……! 저걸 보고만 있는 것만으로도 토할 것 같아……!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ううっ……！　すごく気持ち悪い……！　あれを見てるだけで吐きそうだ……！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Urgh...! I feel sick...! Looking at them makes me vomit...!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "噁……！好想吐……！光看到就覺得反胃……！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อึก...! รู้สึกไม่ดีเลยแฮะ...! แค่มองก็จะอ้วกแล้ว...!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Urgh...! Mình cảm thấy ghê quá...! Nhìn chúng khiến mình buồn nôn...!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "呃呃……！胃里好恶心……！光是看着那东西感觉就要吐了……！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Urgh ...! Mir ist kotzübel ...! Wenn ich sie nur anschaue, habe ich das Gefühl, dass ich mich übergeben muss ...!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Urgh... ! Je me sens mal... j'ai envie de vomir rien qu'en les regardant !"
