L34_1 = "하나, 둘, 셋…… 애들 말대로 2종은 없나? 이정도면 혼자서 어떻게든……."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "一、ニ、三……みんなの言うとおり、第2種はないかな。この程度ならウチ一人でなんとか……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "One, two, and three... And no Category 2s, just like the girls said. I could probably deal with them on my own..."
L33_1.m_Talk_ENG = L34_1
L34_1 = "一、二、三……沒有她們說的二類嗎？那我自己應該還……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หนึ่ง สอง แล้วก็สาม... แถมไม่มีคลาส 2 เหมือนที่สาวๆ ว่าเลยแฮะ ฉันน่าจะจัดการเองได้นิ..."
L33_1.m_Talk_THA = L34_1
L34_1 = "Một, hai, và ba... Và không có Hạng 2, đúng như các cô gái đã nói. Có lẽ mình mình cũng có thể xử lý bọn chúng..."
L33_1.m_Talk_VTN = L34_1
L34_1 = "一、二、三……果然没有2级侵蚀体吗。咱自己对付这么多应该也……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Eins, zwei, drei ... Und keines der Kategorie 2? Ich könnte also wahrscheinlich alleine mit ihnen klarkommen ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Un, deux, trois... Aucun catégorie 2, comme prévu. Je devrais pouvoir m'en occuper seule..."
L33_1.m_Talk_FRA = L34_1
