L36_1[L37_1] = true
L37_1 = "미리네 누나, 겨우 빗자루 하나로 <color=#ffd34c>저것</color>들과 싸우겠다는 거야……?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "まさかマリさん、たったほうき一本で<color=#ffd34c>あれ</color>と戦うつもりなのか……？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "No way... Is Rinae going to fight <color=#ffd34c>them</color> with a single broomstick...?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "宓璃奈姊姊現在是要用一支掃把力抗<color=#ffd34c>那些東西</color>嗎……？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไม่จริงน่า... มิรีนจะเอาไม้กวาดด้ามเดียวไปสู้กับ<color=#ffd34c>พวกมัน</color>เหรอ...?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Không đời nào... Rinae sẽ chiến đấu với <color=#ffd34c>chúng</color> chỉ bằng một cây chổi thôi sao...?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "茉莉奈姐姐，是要用一把扫把对付<color=#ffd34c>那些东西</color>吗……？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hat Rinae etwa vor, <color=#ffd34c>diese Dinger</color> nur mit einem Besen zu bekämpfen ...?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Rinae compte vraiment les affronter ? Juste avec ce <color=#ffd34c>manche à balai</color> ?"
