L38_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L39_1 = "C_F_R"
L38_1.m_Pos = L39_1
L39_1 = "얌전히 이면세계에나 처박혀 있었음 좋았을 낀데…… 마, 니들도 꽤 심심했나 보제?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "大人しく裏世界に引っ込んでればよかったやん……まあ、あんたたちも結構暇だったみたいやな。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It would've been nice if y'all just laid low on Counterside... Well, I reckon it must have been pretty borin’, huh?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "怎麼不乖乖待在異界裡呢……你們是吃飽沒事幹嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ถ้าพวกแกนอนเฉยๆ อยู่ในเคาน์เตอร์ไซด์ก็คงดีแหละน้อ... แต่แหม ฉันว่ามันก็คงน่าเบื่อแหละเนาะ จริงมั้ยนิ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Sẽ thật tuyệt nếu tất cả tụi mày chỉ vật vờ ở Counterside... Chà, mình đã tưởng nó hẳn là nhàm chán lắm chứ?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "乖乖地待在异界多好……看来你们也很无聊啊？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Es wäre schön gewesen, wenn ihr einfach in der Counterside geblieben wärt ... Aber euch muss dort ziemlich langweilig gewesen sein, oder?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous auriez mieux fait de rester planqués dans le Contremonde... ou alors c'est l'ennui qui vous a fait sortir de votre tanière ?"
L38_1.m_Talk_FRA = L39_1
