L39_1.m_Talk_THA = L40_1
L40_1 = "Tao không có nhiều thời gian... Vậy nên tất cả cứ xông lên một lượt đi!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "好了，没时间了，一起上吧！"
