L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "하아, 이거 또 뿐질러 뭇네. 내 아직도 수련이 부족한기가?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "はあ、また折ってもうた。ウチ、まだ修行が足りないんやろか？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "*Huff...* I broke it again. Was all that training not enough?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "哎呀，掃把又斷啦？是我的功力還不夠嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "*แฮ่ก...* สงสัยฉันทำพังอีกแล้วนิ ที่ฝึกๆ มาทั้งหมดไม่ได้ช่วยเลยเรอะ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "*Hộc...* Mình lại làm gãy nó rồi. Đào tạo như thế mà vẫn chưa đủ sao?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "哈啊，这个扫把又打断了。看来是咱的修炼还不够啊？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "*Seufz* Er ist schon wieder kaputt. Habe ich etwa immer noch nicht genug trainiert?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tss, encore cassé. Peut-être que j'ai encore besoin d'entraînement ?"
L46_1.m_Talk_FRA = L47_1
