L48_1 = "CRF or whatever it is... It’s dang hard to control."
L47_1.m_Talk_ENG = L48_1
L48_1 = "要控制CRF還什麼的……好難喔。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "CRF อะไรนี่มัน... ควบคุมยากชะมัด"
L47_1.m_Talk_THA = L48_1
L48_1 = "CRF hay dù nó là cái gì đi chăng nữa... Đều rất khó kiểm soát."
L47_1.m_Talk_VTN = L48_1
L48_1 = "CRF什么的……控制起来真的好难。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Dieses CRS ... ist so schwer zu kontrollieren."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ce truc, là... la FRC ? C'est vraiment pas facile à contrôler."
