L48_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L48_1.m_Pos = "C"
L49_1 = "뭐 하나 제대로 가르쳐주는 사람도 없고."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "何一つちゃんと教えてくれる人もおらへんし。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "There’s no one to guide me properly."
L48_1.m_Talk_ENG = L49_1
L49_1 = "又沒人可以好好教我。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ไม่มีใครมาแนะนำดีๆ ด้วยนิ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Không có ai cho mình biết làm thế nào là đúng cả."
L48_1.m_Talk_VTN = L49_1
L49_1 = "嗯，也没人好好教我。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Weil es niemanden gibt, der es mir richtig beibringen kann."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Surtout si j'ai personne pour me guider..."
L48_1.m_Talk_FRA = L49_1
