L49_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "쌤이 아무리 잘한다 잘한다캐도…… 내 이래갖고 언제 강해질 수 있는긴데……?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "先生がいくらよくやってるって言うても……こんなんでウチ、いつ強くなれるん……？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "No matter how much Teach tells me I’m good... It’s never goin’ to be enough."
L49_1.m_Talk_ENG = L50_1
L50_1 = "老師一定會誇我很棒……但這樣我什麼時候才能變強呢……？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ครูจะบอกว่าฉันเก่งแค่ไหน... ก็ไม่มีวันจะพอหรอก"
L49_1.m_Talk_THA = L50_1
L50_1 = "Cho dù Thầy có nói mình rất giỏi... Sẽ chẳng bao giờ là đủ."
L49_1.m_Talk_VTN = L50_1
L50_1 = "虽然老师说咱做得还不错……但是这样下去，得到什么时候才能变强啊……？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Egal wie sehr der Lehrer mir auch sagt, dass ich gut bin ... so kann ich dennoch nicht mein volles Potenzial entfalten ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Le prof a beau me répéter que je suis douée... c'est pas ça qui va me faire apprendre plus vite !"
L49_1.m_Talk_FRA = L50_1
