L1_1.m_Talk_TWN = L2_1
L2_1 = "ปะ-ปะ-ปะ-เป็นไปไม่ได้...! เธอจัดการสัตว์ประหลาดพวกนั้นในพริบตาเดียวเลย!"
L1_1.m_Talk_THA = L2_1
L2_1 = "k-k-không thể nào...! Chị ấy đã hạ gục những con quái vật đó trong nháy mắt!"
