L5_1 = "ระ-เราฝันไปเหรอนี่...? หรือจะเล่นเกมมากไปนะ? ถ้าไม่ใช่ เราเห็นภาพหลอน–"
L4_1.m_Talk_THA = L5_1
L5_1 = "M-mình đang mơ sao...? Có phải mình chơi game quá độ không? Nếu không, mình đang bị ảo giá-"
L4_1.m_Talk_VTN = L5_1
