L4_1.m_Talk_SCN = L5_1
L5_1 = "T-träume ich gerade ...? Habe ich zu viel gezockt? Oder verliere ich gerade den Verstand ...?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "J-J'ai la berlue, ou quoi ? J'ai peut-être un peu trop forcé sur les jeux hier soir... C'est sûrement une hallucinat─"
