L10_1 = "쳇, 한 마리 놓쳤었네. 꼬맹이! 니 괘안나? 다친 데는 없고?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ちっ、一匹逃してもうた。チビ！　あんた、大丈夫？　ケガはないか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Tch! I missed one. Hey kid! Ya good? Are ya hurt?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "嘖，漏掉一隻！喂，小朋友，你沒事唄？有受傷嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ชิ! พลาดไปตัวนิ เฮ้ เจ้าหนู! เป็นอะไรรึเปล่า? บาดเจ็บมั้ยนิ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chậc! Lại để hụt một đứa rồi. Này nhóc! Khỏe không? Có bị thương không?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "切，漏了一只呢。喂，小不点，你没事吧？没受伤吧？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Mist! Ich habe einen übersehen. Hey, Kleiner! Geht es dir gut? Bist du verletzt?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oups, on dirait que j'en ai raté un. Eh, gamin ! Tout va bien, pas de bobos ?"
L9_1.m_Talk_FRA = L10_1
