L11_1 = "얼라가 어쩌자고 이런 데를 맘대로 들어왔노? "
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ガキのくせに、なんで勝手にここ入って来たん？ "
L10_1.m_Talk_JPN = L11_1
L11_1 = "What brings a helpless kid like yourself in this neighborhood?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "小朋友，你怎麼會跑到這種地方來？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เด็กช่วยตัวเองไม่ได้อย่างเธอมาอยู่อะไรในย่านนี้นิ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Sao một đứa vô dụng như nhóc lại dám mò mẫm tới khu phố này?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "小孩子为什么要随便来这种地方呢？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Was hat ein hilfloses Kind wie du in dieser Nachbarschaft verloren?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Qu'est-ce qu'un mioche comme toi fait ici ? Tu t'es perdu ? "
L10_1.m_Talk_FRA = L11_1
