L30_1.m_Talk_THA = L31_1
L31_1 = "R-rinae...?! C-chuyện gì đã xảy ra với lũ quái vật...?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "茉、茉莉奈姐姐……！？那、那个怪物呢……！？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "R-Rinae ...?! W-was ist mit den Monstern passiert ...?"
