L34_1 = "하아, 어쩌자고 내를 따라왔노? 위험하다 안 하나. 니 디질 뻔했다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "はあ、なんでウチについてきたん？　危ないやん。あんた、死んだかもしれないんやで。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "*Sigh* What were ya thinkin’, followin’ me all the way up there? It was so dangerous. You could’ve died!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "真是的，你幹嘛跟蹤我？很危險欸，你看你差點死掉！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "*เฮ้อ* คิดอะไรถึงตามฉันไปถึงนั่นนิ? บอกแล้วไม่ใช่เรอะว่าอันตราย? จะตายเอานิเธอน่ะ!"
L33_1.m_Talk_THA = L34_1
L34_1 = "*Thở dài* Nhóc nghĩ sao mà theo chị đến tận đó vậy? Chẳng phải chị đã nói nó rất nguy hiểm sao? Nhóc có thể chết đấy!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "诶，你为什么要跟着我？都说了很危险。你差点就挂了。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "*Seufz* Was hast du dir bloß dabei gedacht, mir den ganzen Weg dorthin zu folgen? Es war so gefährlich. Du hättest sterben können!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "*Soupir* Tu peux me dire ce que tu avais en tête pour me suivre jusqu'ici ? C'était dangereux, tu aurais pu mourir !"
L33_1.m_Talk_FRA = L34_1
