L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L35_1.m_Pos = "R"
L36_1 = "됐다. 그런 걸로 치믄 니 같은 얼라한테 꼬리 밟힌 내도 잘못도 있으니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ええよ。あんたみたいなガキにバレたんはウチのせいでもあるし。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "It’s fine. I should have known better to get tailed by a kiddo like yourself."
L35_1.m_Talk_ENG = L36_1
L36_1 = "沒事，真要說的話，怪我自己不小心被你看到唄！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่เป็นไรๆ ฉันเองก็น่าจะรู้นิว่าโดนเด็กแบบเธอตามมา"
L35_1.m_Talk_THA = L36_1
L36_1 = "Được rồi. Lẽ ra bị một tên nhóc bám đuôi thì chị phải nhận ra chứ."
L35_1.m_Talk_VTN = L36_1
L36_1 = "算了，真要算起来，被你这种小屁孩跟踪都没有发觉，咱也有错。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Schon gut. Ich hätte es besser wissen sollen, von einem Kind wie dir beschattet zu werden."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Bah, laisse tomber. C'est de ma faute, j'aurais jamais dû laisser me faire prendre en filature par un morveux comme toi."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
