L37_1 = "그런데 그 괴물들은 대체 뭔가요? 그리고 그 괴물과 싸우던 누나는……."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "でも、あの化け物はいったい何ですか？　それに、あの化け物と戦ってたマリさんは……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "What are those monsters? And how did you fight them off so well...?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "不過那些怪物到底是什麼？還有和怪物對打的姊姊你是……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "สัตว์ประหลาดพวกนั้นมันอะไรกันน่ะครับ? แล้วทำไมคุณสู้พวกมันได้แบบนั้น...?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Những con quái vật đó là sao? Và chị đã chiến đấu với chúng bằng cách nào chứ...?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "姐姐……那些怪物究竟是什么？还有，姐姐为什么能对付那些怪物……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Was waren das für Monster? Und wie hast du sie so gut bekämpft ...?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Mais c'était quoi, ces monstres ? Et comment t'as fait pour les éliminer comme ça... ?"
L36_1.m_Talk_FRA = L37_1
