L40_1 = "스트리트 카운터에 나오는 카운터 같은 거라고. 그럼 대충 알아 듣겠제?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ストリート・カウンターに出るカウンターみたいなもんやで。そう言えば大体わかるやろ？"
L39_1.m_Talk_JPN = L40_1
