L39_1.m_Talk_TWN = L40_1
L40_1 = "เคาน์เตอร์แบบเคาน์เตอร์ในสตรีทเคาน์เตอร์ไง เข้าใจมั้ยนิ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Counter, giống như các Counter trong Counter Đường phố. Hiểu ý chị nói chứ?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "就像《街头制裁者》中出现的制裁者一样，这么说你大概能听懂了吧？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Counter, wie die Counter in Street Counter. Verstehst du, was ich meine?"
L39_1.m_Talk_DEU = L40_1
