L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_DESPAIR"
L44_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "후우, 하기사 무리도 아니겠제…… 이런 얘기. 내도 쌤한테 처음 들었을 땐……"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ふう、まあ、無理もないわ……こんな話。ウチも初めて先生から聞いた時は……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "*Sigh* I reckon it won’t really make sense to ya at the moment... I was like that too when I first heard from Teach–"
L44_1.m_Talk_ENG = L45_1
L45_1 = "呵，也是可以理解啦……老師第一次跟我說的時候我也是嚇到……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "*เฮ้อ* ท่าทางอะไรๆ มันคงดูไม่สมเหตุสมผลไปหมดสินะตอนนี้นิ... ตอนฉันได้ยินจากครูครั้งแรกก็แบบนั้–"
L44_1.m_Talk_THA = L45_1
L45_1 = "*Thở dài* Chị nghĩ rằng điều đó sẽ không thực sự hợp lý lúc này... Chị cũng đã như vậy khi lần đầu tiên nghe được từ Thầy–"
L44_1.m_Talk_VTN = L45_1
L45_1 = "呼，也是，确实很难接受吧……咱第一次听老师说这些事的时候，也吓了一跳……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "*Seufz* Ich denke, es wird im Moment nicht wirklich Sinn für dich ergeben ... Mir ging es auch so, als ich es zum ersten Mal vom Lehrer gehört habe –"
L44_1.m_Talk_DEU = L45_1
L45_1 = "*Soupir* Bah, ça doit te faire un choc. Moi aussi, quand le prof me l'a dit la première fois..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "GAMECIRCLE_ACT2_STAGE3_START@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5000209
L45_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_SERIOUS2"
L45_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L45_1.m_Pos = "C"
L45_1.m_Crash = 10
L46_1 = "괴, 굉장해! 역시…… 역시 카운터는 실제로 존재하는 거였군요! 저, 믿고 있었다구요!"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "す、すごい！　やっぱり……やっぱりカウンターは実際にいたんですね！　僕、信じてたんです！"
L45_1.m_Talk_JPN = L46_1
L46_1 = "A-amazing! So... Counters really do exist! I knew it! I knew it!"
L45_1.m_Talk_ENG = L46_1
L46_1 = "好…好厲害！我就知道……制裁者果然是真實存在的！我一直都深信！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "สะ-สุดยอดไปเลยครับ! งั้น... เคาน์เตอร์ก็มีอยู่จริงสินะครับ! กะแล้วเชียว! กะแล้ว!"
L45_1.m_Talk_THA = L46_1
L46_1 = "T-tuyệt vời! V-vậy là...Counter thực sự tồn tại! Mình biết mà! Mình biết mà!"
L45_1.m_Talk_VTN = L46_1
L46_1 = "好、好酷！果然……制裁者真的存在！我一直都相信的！"
L45_1.m_Talk_SCN = L46_1
L46_1 = "D-das ist ja unglaublich! Also ... gibt es Counter wirklich! Ich habe es doch gewusst!"
L45_1.m_Talk_DEU = L46_1
L46_1 = "C-C'est trop cool ! J'en étais sûr, les Counters existent vraiment ! Je le savais !"
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
