L48_1 = "GAMECIRCLE_ACT2_STAGE3_START@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5000209
L47_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_SERIOUS2"
L47_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L47_1.m_Pos = "C"
L48_1 = "그럼 누나는 몇 등급 카운터에요!? 저도 카운터가 될 수 있을까요? 카운터들의 비밀 단체는 정말로 존재하나요!? 카운터라면 누나도 이세계의 괴물로부터 사람들을 지키는 거죠!? 샐러리맨X처럼!?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "じゃあ、マリさんは何ランクのカウンターなんですか！？　僕もカウンターになれるんでしょうか？　カウンターの秘密団体は、本当に存在しているんですか！？　カウンターなら、マリさんも異世界の化け物からみんなを守ってるんですよね！？　サラリーマンXみたいに！！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "What grade are you?! Can I also be a Counter? Is there really a secret Counter society?! You’re all protecting the world from alien invasions, right?! Like Salaryman X!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "那姊姊你是什麼等級的制裁者！？我也可以成為制裁者嗎？真的有制裁者們的秘密組織嗎！？那姊姊也是在保護地球人類不受到怪物的攻擊嗎！？像上班族X那樣！？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณอยู่เกรดไหนเหรอครับ?! ผมเองก็เป็นเคาน์เตอร์ได้รึเปล่า? สมาคมลับสำหรับเคาน์เตอร์มีจริงมั้ยครับ?! พวกคุณกำลังปกป้องโลกจากการรุกรานของมนุษย์ต่างดาวใช่มั้ย?! เหมือนเคาน์เตอร์น่ะครับ!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chị thuộc hạng mấy?! Em cũng có thể trở thành Counter không? Thực sự có một hội Counter bí mật sao?! Các chị đang bảo vệ thế giới khỏi sự xâm lược của người ngoài hành tinh, đúng chứ?! Như Nhân viên văn phòng X ấy!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "那姐姐是几级制裁者啊！？我也能成为制裁者吗？制裁者的秘密组织真的存在吗！？所有制裁者都能在异界的怪物手中保护人类吧！？就像上班族X先生一样！？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Welche Klasse bist du?! Kann ich auch ein Counter werden? Gibt es wirklich eine geheime Countergesellschaft?! Ihr alle beschützt die Welt vor außerirdischen Invasionen, oder?! Wie Büroangestellter X!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "T'es quel grade, alors ? Je peux devenir un Counter, moi aussi ? Y'a vraiment une organisation secrète comme le dit la rumeur ? Vous protégez le monde contre les invasions extraterrestres, c'est ça ? Comme Salarié X ?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
