L52_1 = 0.15
L50_1[1] = L51_1
L50_1[2] = L52_1
L49_1.m_Bounce = L50_1
L50_1 = "마! 니 장난하나! 그런 근육근육한 아재 말고 최소한 여캐로 해줘야 하는 거 아이가? 평소에 니 내를 어떻게 생각하는긴데?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ちょっと！　あんた、ふざけてんの？　あんなムキムキなおっさんやなくて、せめて女キャラにしてくれへん？　あんた、普段ウチのことをどう思ってるん？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Are ya kiddin’ me, Box?! You should at least refer to a female character, instead of a buff old man! What do ya think I am, huh?!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "喂！你有什麼毛病！怎麼可以拿那種肌肉男來跟我比，起碼要是個女角唄？你到底把我當成什麼啦？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ล้อกันเล่นปะนิบ็อกซ์?! อย่างน้อยก็น่าจะคิดถึงตัวละครหญิงสิไม่ใช่ตาแก่แบบนั้นนิ! คิดว่าฉันเป็นใครนิหา?!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nhóc đang đùa à, Box?! Ít ra nhóc phải liên hệ tới một nhân vật nữ thay vì một lão già quê kệch chứ! Nhóc nghĩ chị là cái gì, hả?!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "喂！你是激动疯了吧？！除了那种浑身都是肌肉的大叔，至少也应该拿个女性角色跟咱相比吧？你平时都是怎么看咱的啊！？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Willst du mich veräppeln, Box?! Du solltest dich zumindest auf eine weibliche Figur beziehen, statt auf einen durchtrainierten alten Mann! Was glaubst du, was ich bin?!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Tu te fous de moi, le carton ? Tu pourrais au moins me comparer à un perso féminin, non ? Plutôt qu'à ce tas de muscles sans cervelle !"
L49_1.m_Talk_FRA = L50_1
