L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5000209
L5_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L5_1.m_bWaitClick = true
