L5_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L5_1.m_Pos = "R"
L5_1.m_Crash = 10
L6_1 = "하, 하하……. 고, 고맙데이. 마, 박스 근데 오늘 일은……."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "は、はは……あ、ありがとう。なあ、ダンボール。でも今日のことは……"
L5_1.m_Talk_JPN = L6_1
L6_1 = "H-ha, ha... Th-thanks. But Box, about today–"
L5_1.m_Talk_ENG = L6_1
L6_1 = "哈，哈哈……謝…謝啦。喂，紙箱，今天的事要保……"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฮะ-ฮ่าฮ่า... ขะ-ขอบคุณนะ แต่ว่านะบ้อกซ์ เรื่องวันนี้นิ–"
L5_1.m_Talk_THA = L6_1
L6_1 = "H-ha, ha... C-cảm ơn. Nhưng Box, về ngày hôm nay–"
L5_1.m_Talk_VTN = L6_1
L6_1 = "哈、哈哈……谢、谢了。喂，箱子君，今天的事……"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Hahaha ... D-danke. Aber Box, was den Vorfall von heute betrifft –"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ha, ha ha... M-Merci, carton. Mais ce qui s'est passé aujourd'hui..."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "GAMECIRCLE_ACT2_STAGE3_START@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5000209
L6_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "BOX_NPC_GAMECIRCLE_X"
L6_1.m_Pos = "L"
L6_1.m_Crash = 20
L7_1 = "걱정마세요, 미리네 누나! 아무한테도 말하지 않을게요! 카운터의 존재는 극비사항이잖아요!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "心配しないでください、マリさん！　誰にも言いません！　カウンターの存在は極秘事項じゃないですか！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Don’t worry, Rinae! I won’t tell a soul! Counters are supposed to remain top secret!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "宓璃奈姊姊，你放心！我不會跟其他人說的！制裁者的事是機密！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ไม่ต้องห่วงครับมิรีน! ผมจะไม่บอกใครสักคนเลย! สิ่งหลงเหลือต้องเป็นความลับสุดยอด!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Đừng lo, Rinae! Em sẽ không hé răng nửa lời! Chuyện về Counter phải là bí mật hàng đầu!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "别担心，茉莉奈姐姐！我谁都不告诉！制裁者的存在是一级机密！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Mach dir keine Sorgen, Rinae! Ich werde es keiner Menschenseele erzählen! Die Existenz der Counter ist schließlich streng geheim!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "T'en fais pas pour ça, je serai muet comme une tombe ! Les Counters doivent agir dans l'ombre, je le sais bien !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "GAMECIRCLE_ACT2_STAGE3_START@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5000209
L7_1.m_CutScenStrID = "GAMECIRCLE_ACT2_STAGE3_START"
L7_1.m_bWaitClick = true
