L7_1.m_Face = "UNIT_DESPAIR"
L7_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L7_1.m_Pos = "R"
L8_1 = "으, 으응. 그쟈. 맞지, 극비사항이다. 극비."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "う、うん。そうや。そうやで、極秘事項やからな。極秘。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Y-yeah. You’re right. It is top secret."
L7_1.m_Talk_ENG = L8_1
L8_1 = "嗯，嗯嗯，沒錯，就是機密。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ชะ-ชั่ย ถูกแล้วนิ ลับสุดยอด"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ừ-ừ. Nhóc nói đúng. Đó là bí mật hàng đầu."
L7_1.m_Talk_VTN = L8_1
L8_1 = "呃、呃嗯，是吧，没错，一级机密……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "J-ja. Du hast recht. Es ist streng geheim."
L7_1.m_Talk_DEU = L8_1
L8_1 = "O-Oui. Exactement, c'est top secret."
L7_1.m_Talk_FRA = L8_1
