L10_1 = "헤헷, 역시 그렇죠? 누나, 구해주셔서 고마워요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "へへっ、やっぱりそうですよね？　マリさん、助けてくれてありがとうございます。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "He he, of course! Thanks for saving me, Rinae."
L9_1.m_Talk_ENG = L10_1
L10_1 = "嘿嘿，我就知道。姊姊，謝謝你剛才救我。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "แหะแหะ แน่อยู่แล้วครับ! ขอบคุณที่ช่วยผมไว้นะครับมิรีน"
L9_1.m_Talk_THA = L10_1
L10_1 = "He he, tất nhiên rồi! Cảm ơn vì đã cứu em, Rinae."
L9_1.m_Talk_VTN = L10_1
L10_1 = "嘿嘿，果然是那样的吧？姐姐，谢谢你救了我。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Hehe, na klar! Danke, dass du mich gerettet hast, Rinae."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Bien sûr, hé hé ! Merci, Rinae. Tu m'as sauvé la vie."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
