L10_1.m_Pos = "C"
L10_1.m_Crash = 15
L11_1 = "그럼, 전 먼저 집에 가볼게요! 내일 봬요!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "じゃあ、僕は先に家に帰りますね。また明日！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I gotta go home now! See you tomorrow!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "那我先回家囉，明天見！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ผมจะกลับบ้านแล้วครับ! พรุ่งนี้เจอกันนะครับ!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Em phải về nhà bây giờ! Hẹn gặp lại vào ngày mai!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "那我先回家了！明天见！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich muss jetzt nach Hause! Bis morgen!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Bon, il faut que je rentre ! On se voit demain !"
L10_1.m_Talk_FRA = L11_1
