L12_1 = "FX_CUTSCEN_FOOTSTEP_RUNNING_02"
L11_1.m_StartFXSoundName = L12_1
L11_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L11_1.m_Pos = "C"
L11_1.m_Crash = 20
L12_1 = "자, 잠깐! 기다리라! 마! 박스! 기다리라니까!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ちょ、ちょっと！　待って！　オイ！　ダンボール！　待ってって！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "W-wait a minute! Hey! Box! Wait up, I said!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "等…先等一下！等等！喂！紙箱！我叫你站住！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ดะ-เดี๋ยวสิ! เฮ้! บ็อกซ์! บอกให้รอก่อน!"
L11_1.m_Talk_THA = L12_1
L12_1 = "C-chờ một chút! Này! Box ơi! Chờ đấy, chị đã nói rồi mà!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "等、等等！等一下！喂，箱子君！等一下！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "W-warte mal! Hey! Box! Ich habe gesagt, dass du warten sollst!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "A-Attends ! Hé, carton !"
L11_1.m_Talk_FRA = L12_1
