L17_1 = "카운터라는 게 진짜로 존재하는 거였고, 미리네 누나가 사실 그 카운터라고……?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "カウンターが本当にいて、マリさんが実はそのカウンターだって……？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Counters are real, and Rinae is one of them...?!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "竟然真的有制裁者，而且宓璃奈姊姊就是制裁者……？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เคาน์เตอร์มีจริง แถมมิรีนเป็นเคาน์เตอร์คนนึงด้วย...?!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Counter là thật, và Riane là một trong số họ...?!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "制裁者居然真的存在，茉莉奈姐姐其实是制裁者……？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Counter sind echt und Rinae ist eine von ihnen ...?!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Les Counters existent vraiment, et Rinae en fait partie... ?"
L16_1.m_Talk_FRA = L17_1
