L17_1.m_Pos = "C"
L17_1.m_Crash = 10
L18_1 = "그럼, 누나들의 선생님이라는 사람도…… 그리고 누나들이 다니는 학교도……?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "じゃあ、先生も……それに、みんなが通ってる学校も……？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Then Teacher... and the school she goes to...?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "那姊姊們的老師……還有姊姊讀的學校也是……？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "งั้นคุณครู... กับโรงเรียนที่เธอไปก็...?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Vậy Thầy... và ngôi trường mà chị ấy học...?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "那姐姐们的老师也……还有姐姐们上的学校也……？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Dann ist der Lehrer ... und die Schule, auf die sie geht ...?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Mais alors, les autres filles... et le professeur... ?"
L17_1.m_Talk_FRA = L18_1
