L35_1.m_CharStrID = "STAR_GAMECIRCLE_NULL_NULL"
L35_1.m_Pos = "C"
L35_1.m_Crash = 20
L36_1 = "으아! 금마 후유증 때문에 혹시 어디 아픈 거 아이가? 어디 잘못된 거 아이가?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ああ、もう！　あいつ、もしかして後遺症でどこか悪うなったんちゃう？　どこかおかしくなったんちゃうん？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Agh! Is he traumatized from the incident? Maybe he’s sick!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "吼！他該不會是有後遺症，哪裡不舒服嗎？還是哪裡有問題？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อึก! เขาช็อกเพราะเรื่องนั้นรึเปล่านะ? อาจจะป่วยก็ได้นิ!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Agh! Có phải nhóc ấy bị chấn thương do vụ đó không? Có lẽ nhóc ấy bị ốm rồi!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "呃啊！那家伙不会是因为后遗症生病了吧？不会是哪里出问题了吧？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Argh! Ist er durch den Vorfall traumatisiert? Oder wurde er vielleicht doch verletzt?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Argh ! C'est peut-être le traumatisme de l'incident de l'autre jour ? Ou alors, il a été blessé ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
