L37_1 = "역시 그때 끝까지 데려다 줄 걸 그랬다! 안 되겠다. 걱정돼서 못 참겠다. 지금이라도……"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "やっぱあの時最後まで送ってやればよかったわ！　あかん。めっちゃ心配や。今にでも……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "I should have taken him home that night...! Okay, I can’t wait any longer. I’m goin’ to–"
L36_1.m_Talk_ENG = L37_1
L37_1 = "果然應該要堅持送他回家的！不行！擔心死人了，我現在就去找……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "วันนั้นฉันน่าจะพาเขาหลับบ้านน้อ...! เอาล่ะ รอไม่ไหวแล้วนิ ฉันจะไป–"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đáng lẽ tôi nên đưa nó về nhà tối hôm đó ...! Được rồi, tôi không thể chờ thêm nữa. Tôi sẽ-"
L36_1.m_Talk_VTN = L37_1
L37_1 = "那天咱就应该送他回家的！不行，太担心了，咱要受不了了，现在……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich hätte ihn in dieser Nacht nach Hause bringen sollen ...! Okay, ich kann nicht länger warten. Ich werde –"
L36_1.m_Talk_DEU = L37_1
L37_1 = "J'aurais dû le raccompagner chez lui... Bon, ça suffit. Pas une seconde à perdre, je vais le─"
L36_1.m_Talk_FRA = L37_1
