L43_1[2] = L45_1
L42_1.m_Bounce = L43_1
L43_1 = "마, 꼬맹이! 니 뭐하다 이제 나타나는긴데? 연락도 안 하고! 걱정했다 안 카나!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ちょっと、じゃりんこ！　あんた、なんで今さら来たんや！　連絡もないし！　心配したやん！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Kiddo! Where were ya all this time?! Ya can't disappear like that! We were worried sick!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "喂，紙箱！你在搞什麼？怎麼現在才來？又不跟我們聯絡！我們會擔心欸！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เจ้าหนู! หายไปไหนมาหลายวันนิ?! หายหัวไปดื้อๆ แบบนี้ไม่ได้นะ! เราก็กลัวจะป่วยกันนิ!"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhóc! Suốt thời gian qua nhóc đi đằng nào vậy?! Nhóc không thể cứ thế biến mất được! Bọn chị đã lo lắng đến phát ốm lên!"
L42_1.m_Talk_VTN = L43_1
L43_1 = "喂！你怎么现在才露面？也不打个电话！大家都很担心你！"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Kleiner! Wo warst du denn die ganze Zeit?! Du kannst doch nicht so einfach verschwinden! Wir waren alle krank vor Sorge!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "C-C'est toi, gamin ? Qu'est-ce qui t'a pris de disparaître comme ça ? Je me suis fait un sang d'encre !"
L42_1.m_Talk_FRA = L43_1
