L48_1 = "뭐, 뭔소리고!? 갑자기 나타나서 뭘 완성했다는 긴데?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "な、何言うてんねん？！　いきなり現れて、何を完成したん！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "F-finish what? Whatcha ramblin’ about?!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "啥，啥東東！？突然冒出來說完成什麼？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อะ-อะไรเสร็จนิ? เพ้อเจ้อไรน่ะ?!"
L47_1.m_Talk_THA = L48_1
L48_1 = "X-xong cái gì cơ? Lầm bầm cái chuyện gì vậy?!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "说、说什么呢！？什么东西没头没脑地完成了？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Was redest du denn da? Du tauchst plötzlich hier auf und redest davon, dass du etwas vollendet hast?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "D-De quoi ? Terminer quoi, qu'est-ce que tu racontes ?"
L47_1.m_Talk_FRA = L48_1
