L51_1 = "리소스는 전부 준비해 뒀어요. 보라 누나, 당장 테스트해 볼 수 있을까요?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "リソースは全部準備しておきました。シホさん、今すぐテストしてみてもいいですか？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I have all the resources ready. Can we test it right now, Bora?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "素材我都準備好了，寶拉姊姊，可以請你現在就測試看看嗎？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ผมเตรียมของพร้อมหมดแล้ว เราทดสอบกันเลยมั้ยครับโบรา?"
L50_1.m_Talk_THA = L51_1
L51_1 = "Em đã chuẩn bị xong mọi tài nguyên. Giờ chúng ta thử nghiệm được chưa, Bora?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "资源我全都准备好了，宝拉姐姐，可以马上测试吗？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich habe alle Ressourcen vorbereitet. Können wir es jetzt testen, Bora?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Toutes les ressources sont prêtes. Bora, on peut passer directement au test ?"
